def binary_search(arr: list, target: int) -> int:
    """Find target index in sorted array, or return -1 if not found."""
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def quick_sort(arr: list) -> list:
    """Sort an array using the QuickSort algorithm."""
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quick_sort(left) + middle + quick_sort(right)

from typing import Dict, List, Set

def dfs(graph: Dict[str, List[str]], start_node: str, visited: Set[str] = None) -> List[str]:
    """Explore a graph deeply using Depth-First Search."""
    if visited is None:
        visited = set()
    visited.add(start_node)
    traversal = [start_node]

    for neighbor in graph.get(start_node, []):
        if neighbor not in visited:
            traversal.extend(dfs(graph, neighbor, visited))
    return traversal

from collections import OrderedDict
from typing import Any, Optional

class LRUCache:
    """LRU Cache with fixed capacity."""
    def __init__(self, capacity: int):
        self.capacity = max(1, capacity)
        self.cache = OrderedDict()

    def get(self, key: str) -> Optional[Any]:
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: str, value: Any) -> None:
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    """Prefix tree for efficient string lookups."""
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def starts_with(self, prefix: str) -> bool:
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

