import json
import os
from typing import Any, Optional

def read_json_file(file_path: str, default: Any = None) -> Any:
    """Safely load a JSON file with fallback default."""
    if not os.path.exists(file_path):
        return default
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception as e:
        print(f"Warning: Failed to read {file_path}: {e}")
        return default

def write_json_file(file_path: str, data: Any, indent: int = 2) -> bool:
    """Safely write data to a JSON file."""
    try:
        os.makedirs(os.path.dirname(os.path.abspath(file_path)), exist_ok=True)
        with open(file_path, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=indent, ensure_ascii=False)
        return True
    except Exception as e:
        print(f"Error writing {file_path}: {e}")
        return False

import time
import functools
from typing import Callable, Any

def retry(max_attempts: int = 3, delay_seconds: float = 0.5, backoff_factor: float = 2.0):
    """Decorator that retries a function upon exception with exponential backoff."""
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            current_delay = delay_seconds
            last_exception = None
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_exception = e
                    if attempt == max_attempts:
                        raise last_exception
                    time.sleep(current_delay)
                    current_delay *= backoff_factor
        return wrapper
    return decorator

